-- Warehouse management extension. Apply after 001_schema.sql.
create table public.warehouse_locations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, code text not null, name text not null, zone text default '', unique(organization_id,code));
create table public.products (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, sku text not null, name text not null, category text default '', reorder_level integer not null default 0, active boolean not null default true, unique(organization_id,sku));
create table public.inventory_units (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, rfid_uid text unique not null, serial_number text, status text not null default 'IN_STOCK', location_id uuid references public.warehouse_locations(id), updated_at timestamptz not null default now());
create table public.stock_movements (id bigint generated always as identity primary key, organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid not null references public.products(id), unit_id uuid references public.inventory_units(id), movement_type text not null, quantity integer not null default 1, from_location uuid references public.warehouse_locations(id), to_location uuid references public.warehouse_locations(id), reference text default '', actor uuid references auth.users(id), device_id uuid references public.devices(id), created_at timestamptz not null default now());
create index stock_movements_org_time on public.stock_movements(organization_id,created_at desc);
alter table warehouse_locations enable row level security; alter table products enable row level security; alter table inventory_units enable row level security; alter table stock_movements enable row level security;
create policy locations_read on warehouse_locations for select to authenticated using(is_org_member(organization_id));
create policy products_read on products for select to authenticated using(is_org_member(organization_id));
create policy units_read on inventory_units for select to authenticated using(exists(select 1 from products p where p.id=product_id and is_org_member(p.organization_id)));
create policy movements_read on stock_movements for select to authenticated using(is_org_member(organization_id));
